  6	  useContext,
  7	  useLayoutEffect,
  8	  useRef,
  9	} from 'react'
 10	import Link from 'next/link'
 11	import { usePathname, useRouter } from 'next/navigation'
 12	
 13	type Direction = 'forward' | 'backward'
 14	type TransitionOptions = {
 15	  update: () => void | Promise<void>
 16	  types?: string[]
 17	}
 18	type BrowserViewTransition = {
 19	  finished: Promise<void>
 20	}
 21	type ViewTransitionDocument = Document & {
 22	  startViewTransition?: (
 23	    options: TransitionOptions | (() => void | Promise<void>),
 24	  ) => BrowserViewTransition
 25	}
 26	
 27	type NavigateWithTransition = (href: string, direction: Direction) => void
 28	
 29	const TransitionContext = createContext<NavigateWithTransition | null>(null)
 30	
 31	export function ViewTransitions({ children }: { children: React.ReactNode }) {
 32	  const router = useRouter()
 33	  const pathname = usePathname()
 34	  const pendingRoute = useRef<{
 35	    pathname: string
 36	    finish: () => void
 37	  } | null>(null)
 38	
 39	  useLayoutEffect(() => {
 40	    const pending = pendingRoute.current
 41	    if (pending && pending.pathname === pathname) pending.finish()
 42	  }, [pathname])
 43	
 44	  const navigate = useCallback<NavigateWithTransition>(
 45	    (href, direction) => {
 46	      const targetPath = new URL(href, window.location.href).pathname
 47	      if (targetPath === pathname) {
 48	        router.push(href)
 49	        return
 50	      }
 51	
 52	      const documentWithTransitions = document as ViewTransitionDocument
 53	      const startViewTransition = documentWithTransitions.startViewTransition
 54	      const reducedMotion = window.matchMedia(
 55	        '(prefers-reduced-motion: reduce)',
 56	      ).matches
 57	
 58	      if (reducedMotion) {
 59	        router.push(href)
 60	        return
 61	      }
 62	
 63	      if (!startViewTransition) {
 64	        document.documentElement.dataset.navigationDirection = direction
 65	        document.documentElement.dataset.cssNavigationFallback = 'true'
 66	        router.push(href)
 67	        window.setTimeout(() => {
 68	          delete document.documentElement.dataset.navigationDirection
 69	          delete document.documentElement.dataset.cssNavigationFallback
 70	        }, 360)
 71	        return
 72	      }
 73	
 74	      document.documentElement.dataset.navigationDirection = direction
 75	      let timeout = 0
 76	      let pending: { pathname: string; finish: () => void } | null = null
 77	      const finish = () => {
 78	        window.clearTimeout(timeout)
 79	        if (pendingRoute.current === pending) pendingRoute.current = null
 80	      }
 81	
 82	      try {
 83	        const transition = startViewTransition.call(documentWithTransitions, {
 84	          types: [direction],
 85	          update: () =>
 86	            new Promise<void>((resolve) => {
 87	              pending = {
 88	                pathname: targetPath,
 89	                finish: () => {
 90	                  finish()
 91	                  resolve()
 92	                },
 93	              }
 94	              pendingRoute.current = pending
 95	              timeout = window.setTimeout(() => {
 96	                finish()
 97	                resolve()
 98	              }, 1500)
 99	              router.push(href)
100	            }),
101	        })
102	        const clearDirection = () => {
103	          delete document.documentElement.dataset.navigationDirection
104	        }
105	        void transition.finished.then(clearDirection, clearDirection)
106	      } catch {
107	        finish()
108	        delete document.documentElement.dataset.navigationDirection
109	        router.push(href)
110	      }
111	    },
112	    [pathname, router],
113	  )
114	
115	  return (
116	    <TransitionContext.Provider value={navigate}>
117	      {children}
118	    </TransitionContext.Provider>
119	  )
120	}
