122	export function TransitionLink({
123	  href,
124	  direction,
125	  className,
126	  children,
127	}: {
128	  href: string
129	  direction: Direction
130	  className?: string
131	  children: React.ReactNode
132	}) {
133	  const navigate = useContext(TransitionContext)
134	  if (!navigate) throw new Error('TransitionLink must be inside ViewTransitions')
135	
136	  return (
137	    <Link
138	      href={href}
139	      className={className}
140	      onNavigate={(event) => {
141	        event.preventDefault()
142	        navigate(href, direction)
143	      }}
144	    >
145	      {children}
146	    </Link>
147	  )
148	}
